// ──────────────────────────── tests ──────────────────────────────────────

test('sums price times quantity for every line', () => {
  eq(cartTotal(cart), 30);
});

test('an empty cart totals 0', () => {
  eq(cartTotal([]), 0);
});

test('rounds money to two decimals', () => {
  eq(cartTotal([{ sku: 'nut', price: 0.1, qty: 3 }]), 0.3);
});

test('appends a line for a sku the cart has never seen', () => {
  const next = withItem(cart, { sku: 'ink', price: 3, qty: 1 });
  eq(next.length, 3);
  eq(next[2], { sku: 'ink', price: 3, qty: 1 });
});

test('bumps the quantity of an existing sku in place', () => {
  const next = withItem(cart, { sku: 'mug', price: 12.5, qty: 1 });
  eq(next.length, 2);
  eq(next[0], { sku: 'mug', price: 12.5, qty: 3 });
});

test('leaves the original cart untouched', () => {
  const next = withItem(cart, { sku: 'mug', price: 12.5, qty: 1 });
  eq(cart[0].qty, 2);
  ok(next !== cart, 'must return a new array');
});

test('shares the lines it did not change with the original', () => {
  const next = withItem(cart, { sku: 'mug', price: 12.5, qty: 1 });
  ok(next[1] === cart[1], 'untouched lines can be reused by reference');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('damage subtracts from hp and returns a new object', () => {
  const next = nextState(state, { type: 'damage', amount: 30 });
  eq(next.hp, 50);
  ok(next !== state, 'a change must produce a new object');
});

test('hp never drops below 0', () => {
  eq(nextState(state, { type: 'damage', amount: 999 }).hp, 0);
});

test('healing is capped at 100', () => {
  eq(nextState(state, { type: 'heal', amount: 50 }).hp, 100);
});

test('score adds points and leaves hp alone', () => {
  const next = nextState(state, { type: 'score', points: 5 });
  eq(next.score, 125);
  eq(next.hp, 80);
});

test('rename replaces only the name', () => {
  eq(nextState(state, { type: 'rename', name: 'Bo' }), {
    name: 'Bo',
    hp: 80,
    score: 120,
  });
});

test('the input state is never mutated', () => {
  nextState(state, { type: 'damage', amount: 30 });
  nextState(state, { type: 'score', points: 5 });
  eq(state, { name: 'Ada', hp: 80, score: 120 });
});

test('an unknown event returns the very same state object', () => {
  const next = nextState(state, { type: 'sneeze' });
  ok(next === state, 'no change means no new object');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('addTodo appends to the end', () => {
  const next = addTodo(todos, { id: 3, text: 'sleep', done: false });
  eq(next.length, 3);
  eq(next[2].text, 'sleep');
});

test('addTodo leaves the original list at its old length', () => {
  addTodo(todos, { id: 3, text: 'sleep', done: false });
  eq(todos.length, 2);
});

test('removeTodo drops the matching id', () => {
  eq(removeTodo(todos, 1), [{ id: 2, text: 'check in', done: false }]);
});

test('removing an id that is not there returns an equal copy', () => {
  const next = removeTodo(todos, 99);
  eq(next, todos);
  ok(next !== todos, 'still a new array');
});

test('updateTodo merges the changes into the matching item', () => {
  const next = updateTodo(todos, 2, { done: true });
  eq(next[1], { id: 2, text: 'check in', done: true });
});

test('updateTodo reuses the items it did not touch', () => {
  const next = updateTodo(todos, 2, { done: true });
  ok(next[0] === todos[0], 'unchanged items keep their identity');
});

test('updateTodo does not mutate the item it replaces', () => {
  updateTodo(todos, 2, { done: true });
  eq(todos[1].done, false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('setTheme changes the value three levels down', () => {
  eq(setTheme(settings, 'light').profile.display.theme, 'light');
});

test('setTheme keeps the siblings on the path', () => {
  const next = setTheme(settings, 'light');
  eq(next.profile.display.density, 'cozy');
  eq(next.profile.name, 'Ada');
});

test('setTheme shares the branches it did not visit', () => {
  const next = setTheme(settings, 'light');
  ok(next.notifications === settings.notifications, 'off-path branch reused');
  ok(next.profile !== settings.profile, 'on-path branch copied');
});

test('setTheme leaves the frozen original alone', () => {
  setTheme(settings, 'light');
  eq(settings.profile.display.theme, 'dark');
});

test('setIn rebuilds every object along the path', () => {
  const next = setIn(settings, ['notifications', 'email', 'marketing'], true);
  eq(next.notifications.email.marketing, true);
  eq(next.notifications.email.security, true);
  ok(next.profile === settings.profile, 'other branches are shared');
});

test('setIn creates a missing step as a plain object', () => {
  eq(setIn({ a: 1 }, ['b', 'c'], 2), { a: 1, b: { c: 2 } });
});

test('setIn with an empty path is just the new value', () => {
  eq(setIn({ a: 1 }, [], 'replaced'), 'replaced');
});

test('updateIn applies a function to what is already there', () => {
  const next = updateIn(settings, ['profile', 'name'], (n) => n.toUpperCase());
  eq(next.profile.name, 'ADA');
  eq(settings.profile.name, 'Ada');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('applies one function per named key', () => {
  const next = evolve(user, {
    name: (s) => s.trim(),
    email: (s) => s.toLowerCase(),
  });
  eq(next.name, 'ada lovelace');
  eq(next.email, 'ada@example.com');
});

test('copies keys that have no transform', () => {
  const next = evolve(user, { name: (s) => s.trim() });
  eq(next.profile, { views: 41, bio: 'first programmer' });
  ok(next.tags === user.tags, 'untouched values keep their identity');
});

test('ignores transforms for keys the object does not have', () => {
  const next = evolve({ a: 1 }, { a: (n) => n + 1, zzz: (n) => n * 100 });
  eq(next, { a: 2 });
});

test('recurses when the transform is an object', () => {
  const next = evolve(user, { profile: { views: (n) => n + 1 } });
  eq(next.profile, { views: 42, bio: 'first programmer' });
});

test('array values are handled by ordinary functions', () => {
  const next = evolve(user, { tags: (list) => [...list, 'analytical'] });
  eq(next.tags, ['math', 'engines', 'analytical']);
  eq(user.tags, ['math', 'engines']);
});

test('never mutates the input, at any depth', () => {
  evolve(user, { name: (s) => s.trim(), profile: { views: (n) => n + 1 } });
  eq(user.name, '  ada lovelace ');
  eq(user.profile.views, 41);
});

test('an empty transform map returns an equal copy', () => {
  const next = evolve(user, {});
  eq(next, user);
  ok(next !== user, 'still a fresh object');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('pipe runs its functions left to right', () => {
  eq(pipe(trim, upper, exclaim)('  hi '), 'HI!');
});

test('compose runs its functions right to left', () => {
  eq(compose(exclaim, upper, trim)('  hi '), 'HI!');
});

test('order matters — the same functions, flipped, differ', () => {
  eq(pipe(exclaim, trim)('  hi '), 'hi !');
});

test('the first function receives every argument', () => {
  const add = (a, b) => a + b;
  eq(pipe(add, (n) => n * 10)(2, 3), 50);
  eq(compose((n) => n * 10, add)(2, 3), 50);
});

test('with no functions the input comes straight back', () => {
  eq(pipe()('untouched'), 'untouched');
  eq(compose()('untouched'), 'untouched');
});

test('the composed function is reusable', () => {
  const shout = pipe(trim, upper, exclaim);
  eq(shout(' a '), 'A!');
  eq(shout(' b '), 'B!');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('normalize cleans up the name, the email and the plan', () => {
  const user = normalize(raw);
  eq(user.name, 'Ada Lovelace');
  eq(user.email, 'ada@example.com');
  eq(user.plan, 'pro');
});

test('normalize survives an empty name', () => {
  eq(normalize({ name: '   ', email: 'a@b.c', plan: 'free' }).name, '');
});

test('normalize does not mutate the raw record', () => {
  normalize(raw);
  eq(raw.plan, 'PRO');
});

test('validate reports an empty error list for a clean record', () => {
  eq(validate({ name: 'Ada', email: 'a@b.c', plan: 'pro' }).errors, []);
});

test('validate names every problem it finds, in order', () => {
  const bad = validate({ name: '', email: 'nope', plan: 'platinum' });
  eq(bad.errors, ['name is required', 'email is invalid', 'unknown plan']);
});

test('format builds a label for a valid signup', () => {
  const user = format({
    name: 'Ada Lovelace',
    email: 'ada@example.com',
    plan: 'pro',
    errors: [],
  });
  eq(user.valid, true);
  eq(user.label, 'Ada Lovelace <ada@example.com> (pro)');
});

test('format leaves the label null when there are errors', () => {
  const user = format({ name: '', email: 'x', plan: 'pro', errors: ['boom'] });
  eq(user.valid, false);
  eq(user.label, null);
});

test('processSignup runs all three steps', () => {
  eq(processSignup(raw), {
    name: 'Ada Lovelace',
    email: 'ada@example.com',
    plan: 'pro',
    errors: [],
    valid: true,
    label: 'Ada Lovelace <ada@example.com> (pro)',
  });
});

