test('sums the squares of the even numbers', () => {
  eq(sumOfSquaresOfEvens([1, 2, 3, 4]), 20);
});

test('returns 0 when nothing is even', () => {
  eq(sumOfSquaresOfEvens([1, 3, 5]), 0);
  eq(sumOfSquaresOfEvens([]), 0);
});

test('counts negative even numbers too', () => {
  eq(sumOfSquaresOfEvens([-2, 7]), 4);
});

test('finds the longest name among active users', () => {
  eq(longestActiveName(users), 'Grace');
});

test('the first of two equally long names wins', () => {
  eq(
    longestActiveName([
      { name: 'Bo', active: true },
      { name: 'Al', active: true },
    ]),
    'Bo'
  );
});

test('returns null when nobody is active', () => {
  eq(longestActiveName([{ name: 'Alexandra', active: false }]), null);
  eq(longestActiveName([]), null);
});

test('formats one padded line per item', () => {
  eq(receiptLines(items), [
    '2 x Mug.............25.00',
    '1 x Ink.............3.00',
  ]);
});

test('skips lines with a quantity of 0', () => {
  eq(receiptLines(items).length, 2);
  eq(receiptLines([{ name: 'Pen', qty: 0, price: 1.25 }]), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('not flips the answer of a predicate', () => {
  const isOdd = not((n) => n % 2 === 0);
  eq(isOdd(3), true);
  eq(isOdd(4), false);
});

test('allPass demands every predicate, anyPass just one', () => {
  const big = (n) => n > 10;
  const even = (n) => n % 2 === 0;
  eq(allPass([big, even])(12), true);
  eq(allPass([big, even])(11), false);
  eq(anyPass([big, even])(11), true);
  eq(anyPass([big, even])(3), false);
});

test('an empty list passes allPass and fails anyPass', () => {
  eq(allPass([])('anything'), true);
  eq(anyPass([])('anything'), false);
});

test('allPass stops at the first predicate that fails', () => {
  const later = spy(() => true);
  eq(allPass([() => false, later])('x'), false);
  eq(later.callCount, 0);
});

test('predicates receive every argument they were called with', () => {
  const sameCity = (a, b) => a.city === b.city;
  eq(allPass([sameCity])({ city: 'Rome' }, { city: 'Rome' }), true);
});

test('buildFilter with no criteria keeps everything', () => {
  eq(products.filter(buildFilter({})).length, 4);
});

test('buildFilter combines price and stock', () => {
  const cheapAndAvailable = buildFilter({ maxPrice: 30, inStock: true });
  eq(names(products.filter(cheapAndAvailable)), [
    'Travel Mug',
    'Notebook',
    'Mug Warmer',
  ]);
});

test('buildFilter matches tags and is case-insensitive on query', () => {
  eq(names(products.filter(buildFilter({ tag: 'kitchen' }))), [
    'Travel Mug',
    'Mug Warmer',
  ]);
  eq(names(products.filter(buildFilter({ query: 'MUG' }))), [
    'Travel Mug',
    'Mug Warmer',
  ]);
  ok(products.filter(buildFilter({ query: 'zzz' })).length === 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('defaults to dollars with two decimals', () => {
  eq(makeFormatter({})(1234.5), '$1,234.50');
});

test('uses the configured symbol and decimal places', () => {
  eq(makeFormatter({ symbol: '€', decimals: 0 })(1234.5), '€1,235');
});

test('groups every three digits with the configured separator', () => {
  eq(makeFormatter({ symbol: '', thousands: ' ' })(1000000), '1 000 000.00');
  eq(makeFormatter({})(999), '$999.00');
});

test('the sign goes outside the symbol', () => {
  eq(makeFormatter({})(-1234.5), '-$1,234.50');
});

test('two formatters from the same factory stay independent', () => {
  const dollars = makeFormatter({});
  const yen = makeFormatter({ symbol: '¥', decimals: 0 });
  eq(dollars(5), '$5.00');
  eq(yen(5), '¥5');
  eq(dollars(5), '$5.00');
});

test('tax is charged on the subtotal, not the shipping, by default', () => {
  const calc = makeTaxCalculator({ rate: 0.08 });
  eq(calc({ subtotal: 100, shipping: 10 }), { tax: 8, total: 118 });
});

test('shippingTaxable puts shipping into the taxable base', () => {
  const calc = makeTaxCalculator({ rate: 0.08, shippingTaxable: true });
  eq(calc({ subtotal: 100, shipping: 10 }), { tax: 8.8, total: 118.8 });
});

test('one configured calculator handles many orders', () => {
  const calc = makeTaxCalculator({ rate: 0.1 });
  eq(calc({ subtotal: 19.99, shipping: 0 }).tax, 2);
  eq(calc({ subtotal: 5, shipping: 2.5 }).total, 8);
  ok(typeof calc === 'function');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a record that satisfies every rule has no errors', () => {
  eq(validate()({ name: 'Ada', age: 41 }), []);
});

test('a failing check becomes a { field, message } object', () => {
  eq(validate()({ name: '', age: 41 }), [
    { field: 'name', message: 'name is required' },
  ]);
});

test('every field is checked, in the order the rules were given', () => {
  eq(validate()({ name: '', age: 15 }), [
    { field: 'name', message: 'name is required' },
    { field: 'age', message: 'must be 18 or older' },
  ]);
});

test('only the first failing check of a field is reported', () => {
  eq(validate()({ name: 'Ada', age: 'old' }), [
    { field: 'age', message: 'age must be a number' },
  ]);
});

test('a missing field reaches the predicate as undefined', () => {
  eq(validate()({ name: 'Ada' }), [
    { field: 'age', message: 'age must be a number' },
  ]);
});

test('a predicate can compare against the whole record', () => {
  const check = makeValidator({
    confirm: [[(v, record) => v === record.password, 'passwords must match']],
  });
  eq(check({ password: 'a', confirm: 'a' }), []);
  eq(check({ password: 'a', confirm: 'b' }), [
    { field: 'confirm', message: 'passwords must match' },
  ]);
});

test('a field with no checks can never fail', () => {
  eq(makeValidator({ anything: [] })({ anything: null }), []);
});

test('one validator is reusable across many records', () => {
  const check = validate();
  eq(check({ name: 'Ada', age: 41 }).length, 0);
  eq(check({ name: '', age: 41 }).length, 1);
  ok(typeof check === 'function');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('passes straight through when given everything at once', () => {
  eq(curry(add3)(1, 2, 3), 6);
});

test('accepts one argument at a time', () => {
  eq(curry(add3)(1)(2)(3), 6);
});

test('accepts any grouping of the arguments', () => {
  eq(curry(add3)(1, 2)(3), 6);
  eq(curry(add3)(1)(2, 3), 6);
});

test('a partial can be reused without being used up', () => {
  const add10 = curry(add3)(10);
  eq(add10(1)(2), 13);
  eq(add10(5)(5), 20);
});

test('two partials of the same function do not share arguments', () => {
  const add = curry(add3);
  const from1 = add(1);
  const from100 = add(100);
  eq(from1(2, 3), 6);
  eq(from100(2, 3), 105);
});

test('arity comes from the declared parameters', () => {
  const join4 = (a, b, c, d) => [a, b, c, d].join('-');
  eq(curry(join4)('a')('b')('c')('d'), 'a-b-c-d');
  eq(curry((a, b) => a * b)(6)(7), 42);
});

test('the wrapped function is not called until it is saturated', () => {
  const calls = [];
  const raw = (a, b) => {
    calls.push([a, b]);
    return a + b;
  };
  const partial = curry(raw)(1);
  eq(calls.length, 0);
  eq(partial(2), 3);
  eq(calls, [[1, 2]]);
});

test('a zero-argument function fires on the first call', () => {
  eq(curry(() => 7)(), 7);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('threads a value through async steps', async () => {
  const run = pipeAsync(
    async (n) => n + 1,
    async (n) => n * 10
  );
  eq(await run(1), 20);
});

test('plain synchronous steps work too', async () => {
  const run = pipeAsync((n) => n + 1, async (n) => n * 2, String);
  eq(await run(4), '10');
});

test('the first step receives every argument', async () => {
  const run = pipeAsync(async (a, b) => a + b, (n) => n * 2);
  eq(await run(2, 3), 10);
});

test('steps run one after another, not at the same time', async () => {
  const log = [];
  const step = (tag, ms) => async (text) => {
    await sleep(ms);
    log.push(tag);
    return text + tag;
  };
  const run = pipeAsync(step('a', 20), step('b', 1));
  eq(await run(''), 'ab');
  eq(log, ['a', 'b'], 'a must finish before b starts');
});

test('rejects with the error thrown by the failing step', async () => {
  const run = pipeAsync(
    async (n) => n,
    async () => {
      throw new Error('step two blew up');
    }
  );
  await rejects(() => run(1), 'step two blew up');
});

test('the steps after a failure never run', async () => {
  const reached = [];
  const run = pipeAsync(
    async () => {
      throw new Error('nope');
    },
    async (n) => {
      reached.push(n);
      return n;
    }
  );
  await rejects(() => run(1));
  eq(reached, []);
});

test('with no steps the input comes back', async () => {
  eq(await pipeAsync()('untouched'), 'untouched');
});

test('the pipeline can be run more than once', async () => {
  const run = pipeAsync(async (n) => n * 2);
  eq(await run(2), 4);
  eq(await run(3), 6);
  ok(typeof run === 'function');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('map transforms the value inside the box', () => {
  eq(Maybe(5).map((n) => n * 2).getOrElse(0), 10);
  eq(Maybe.of('ada').map((s) => s.toUpperCase()).getOrElse(''), 'ADA');
});

test('null and undefined are Nothing', () => {
  ok(Maybe(null).isNothing);
  ok(Maybe(undefined).isNothing);
  eq(Maybe(null).getOrElse('fallback'), 'fallback');
});

test('0, empty string and false are ordinary values', () => {
  eq(Maybe(0).isNothing, false);
  eq(Maybe(0).getOrElse(99), 0);
  eq(Maybe('').getOrElse('fallback'), '');
  eq(Maybe(false).getOrElse(true), false);
});

test('map on a Nothing never calls the function', () => {
  let called = false;
  const result = Maybe(null).map(() => {
    called = true;
    return 'x';
  });
  eq(called, false);
  ok(result.isNothing, 'still a Maybe, still Nothing');
});

test('a map that returns null produces a Nothing', () => {
  const box = Maybe({ a: 1 }).map((o) => o.missing);
  ok(box.isNothing);
  eq(box.map((v) => v.toUpperCase()).getOrElse('safe'), 'safe');
});

test('chain flattens a function that returns a Maybe', () => {
  const half = (n) => (n % 2 === 0 ? Maybe(n / 2) : Maybe(null));
  eq(Maybe(8).chain(half).getOrElse('odd'), 4);
  eq(Maybe(7).chain(half).getOrElse('odd'), 'odd');
});

test('filter turns a failing value into Nothing', () => {
  const big = (n) => n > 10;
  eq(Maybe(42).filter(big).getOrElse(0), 42);
  eq(Maybe(4).filter(big).getOrElse(0), 0);
  ok(Maybe(null).filter(big).isNothing);
});

test('long chains stay safe from end to end', () => {
  const shout = (box) =>
    box
      .map((s) => s.trim())
      .filter((s) => s.length > 0)
      .map((s) => s.toUpperCase())
      .getOrElse('(nothing)');
  eq(shout(Maybe('  hi ')), 'HI');
  eq(shout(Maybe('   ')), '(nothing)');
  eq(shout(Maybe(null)), '(nothing)');
});

