  const half = (n) => (n % 2 === 0 ? Maybe(n / 2) : Maybe(null));
  eq(Maybe(8).chain(half).getOrElse('odd'), 4);
  eq(Maybe(7).chain(half).getOrElse('odd'), 'odd');
});

