      .map((s) => s.trim())
      .filter((s) => s.length > 0)
      .map((s) => s.toUpperCase())
      .getOrElse('(nothing)');
  eq(shout(Maybe('  hi ')), 'HI');
  eq(shout(Maybe('   ')), '(nothing)');
  eq(shout(Maybe(null)), '(nothing)');
