  const result = signupValidator()(good);
  eq(result.ok, true);
  ok(result.value === good, 'the input, not a copy');
});

test('one broken rule gives one error', () => {
  const result = signupValidator()({ ...good, email: 'nope' });
  eq(result, {
    ok: false,
    errors: [{ field: 'email', message: 'email must contain @' }],
  });
});

