  const validate = validateAll(
    check('email', 'email is required', isFilled),
    check('email', 'email must contain @', hasAt)
  );
  eq(validate({ email: '' }).errors.length, 2);
  eq(validate({ email: 'ada@x.dev' }), { ok: true, value: { email: 'ada@x.dev' } });
